&reftitle.description;
boolftp_chdir FTP\Connectionftp stringdirectory
Cambia la directory corrente con quella specificata.

&reftitle.parameters;




   ftp

     &ftp.parameter.ftp;



   directory



     La directory di destinazione.

&reftitle.returnvalues;


 &return.success;
 Se il cambio di directory fallisce, PHP emetterà anche un avviso.

  &reftitle.examples;



    Esempio di ftp_chdir


<?php

// stabilisce la connessione di base
$ftp = ftp_connect($ftp_server); 

// si collega con nome utente e password
$login_result = ftp_login($ftp, $ftp_user_name, $ftp_user_pass); 

// controlla la connessione
if ((!$ftp) || (!$login_result)) {
    die("La connessione FTP non è riuscita!");
}

echo "Directory corrente: " . ftp_pwd($ftp) . "\n";

// tenta di passare alla directory somedir
if (ftp_chdir($ftp, "somedir")) {
    echo "Ora la directory corrente è: " . ftp_pwd($ftp) . "\n";
} else { 
    echo "Impossibile cambiare directory\n";
}

// chiude la connessione
ftp_close($ftp);
?>
